const $=s=>document.querySelector(s);
function newTripId(){
  if(typeof crypto.randomUUID==='function')return crypto.randomUUID();
  const bytes=crypto.getRandomValues(new Uint8Array(16));
  bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;
  const hex=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');
  return `${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`;
}
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photo=(id,w=1100)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
const photos={japan:'photo-1493976040374-85c8e12f0c0e',italy:'photo-1516483638261-f4dbaf036963',bali:'photo-1537996194471-e657df975ab4',mountain:'photo-1464822759023-fed622ff2c3b'};
const initial={saved:[],liked:[],visited:['USA','GBR','FRA','ESP','PRT','ITA','DEU','NLD','CHE','SGP','MYS','THA','IDN','VNM','PHL','KHM','LAO','JPN','KOR','CHN'],trips:[{id:'kyoto',title:'The quieter side of Kyoto',place:'Kyoto, Japan',author:'Sophie Chen',days:5,image:'japan',status:'Completed',own:false,stops:[{name:'Wander through Arashiyama',done:false},{name:'Coffee beside the Kamo River',done:false},{name:'An evening in Gion',done:false}]},{id:'italy',title:'Slow days on the Italian coast',place:'Cinque Terre, Italy',author:'Oliver James',days:7,image:'italy',status:'Completed',own:false,stops:[{name:'Explore the lanes of Manarola',done:false},{name:'Walk to the harbour',done:false}]},{id:'bali',title:'A little reset in Bali',place:'Ubud, Indonesia',author:'Jamie Lee',days:6,image:'bali',status:'Planned',own:true,stops:[{name:'Check in and explore Ubud',done:false},{name:'Morning at the rice terraces',done:false}]}]};
let state=structuredClone(initial),filter='all',query='',tripTab='itinerary',toastTimer;
try{const saved=JSON.parse(localStorage.getItem('roam-prototype-v1'));if(saved&&Array.isArray(saved.trips)&&Array.isArray(saved.saved)&&Array.isArray(saved.liked)&&Array.isArray(saved.visited))state=saved}catch{}
// Add the real trip once, preserving existing browser trips and later edits.
if(!state.trips.some(t=>t.id===importedTrip.id)){state.trips.unshift(structuredClone(importedTrip));try{localStorage.setItem('roam-prototype-v1',JSON.stringify(state))}catch{}}
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3000)}
function persist(){try{localStorage.setItem('roam-prototype-v1',JSON.stringify(state))}catch{notify('Storage unavailable. Changes last for this session.')}}
function nav(){const page=location.hash.slice(1)||'feed';$('nav').innerHTML=[['feed','◉','Friends feed'],['explore','⌕','Explore'],['trips','▤','My trips'],['profile','◎','My passport']].map(([id,icon,label])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span>${icon}</span>${label}</a>`).join('')}
function card(t){return `<article class="card"><div class="card-cover ${t.imported?'china-card':''}"><a class="cover-link" href="#trip/${t.id}" aria-label="Open ${escapeHTML(t.title)} itinerary">${t.imported?'<div class="china-card-title" aria-hidden="true">杭州 / 上海<small>WEST LAKE → THE BUND</small></div>':`<img src="${photo(photos[t.image]||photos.mountain)}" alt="${escapeHTML(t.place)}" loading="lazy">`}</a><button class="save" data-save="${t.id}" aria-label="Save ${escapeHTML(t.title)}" aria-pressed="${state.saved.includes(t.id)}">${state.saved.includes(t.id)?'★':'☆'}</button><span class="tag">${t.imported?tripDates(t):t.days+' DAYS'} · ${escapeHTML(t.status.toUpperCase())}</span></div><div class="card-body"><div class="person"><span class="avatar">${escapeHTML(t.author.split(' ').map(s=>s[0]).join(''))}</span>${escapeHTML(t.author)}</div><h3><a href="#trip/${t.id}">${escapeHTML(t.title)}</a></h3><span class="muted">↗ ${escapeHTML(t.place)}</span><a class="view-itinerary" href="#trip/${t.id}">View itinerary →</a><div class="card-meta"><span>${t.stops.length} itinerary stops</span><button data-like="${t.id}" aria-pressed="${state.liked.includes(t.id)}" style="border:0;padding:0;background:none">${state.liked.includes(t.id)?'♥ Liked':'♡ Like'}</button></div></div></article>`}
function intro(title,sub){return `<div class="intro"><h1>${title}</h1><div class="muted">${sub}</div></div>`}
function render(){renderPage();mountPhotoGallery()}
function renderPage(){nav();const route=location.hash.slice(1)||'feed';$('#breadcrumb').textContent=route==='profile'?'A life measured in memories':'Your daily dose of elsewhere';if(route.startsWith('trip/'))return detail(route.split('/')[1]);if(route==='profile')return profile();if(route==='travel')return travelSettings();let content='';if(route==='feed'){content=intro('Good places. Better stories.','A little inspiration from the people you follow.')+travelTools()+importedOverview(state.trips.find(t=>t.id===importedTrip.id))+`<section class="hero"><img src="${photo(photos.mountain,1600)}" alt="Sunlight over dramatic alpine mountains"><div><span class="kicker">THE WORLD IS BETTER SHARED</span><h2>Your next chapter<br>starts somewhere new.</h2><p>Find a place. Borrow a little inspiration. Make it yours.</p><button data-go="explore">Find your next adventure ↗</button></div></section><div class="layout"><section><div class="section-head"><h2>From your circle</h2><span class="muted">Example friend trips · Open a cover or View itinerary</span></div><div class="grid">${state.trips.filter(t=>!t.own).map(card).join('')}</div></section><div class="rail"><div class="rail-box"><span class="kicker">OUT IN THE WORLD</span><h3 style="margin-top:15px">Friends, elsewhere</h3><div class="friend"><span class="avatar">SC</span><div>Sophie Chen<small>Exploring Japan · sample</small></div></div><div class="friend"><span class="avatar">OJ</span><div>Oliver James<small>Somewhere in Italy · sample</small></div></div></div><div class="rail-box"><span class="kicker">YOUR TRAVEL PASSPORT</span><h3 style="font-size:32px;margin-bottom:0">${state.visited.length} countries</h3><p>A world of memories. And so much still to discover.</p><button data-go="profile">View your map ↗</button></div><div class="quote">“Collect moments.<br>Leave a little room<br>for the unexpected.”</div></div></div>`}else{const tripsPage=route==='trips';let list=state.trips.filter(t=>tripsPage?(filter==='saved'?state.saved.includes(t.id):t.own):!t.imported).filter(t=>(t.title+' '+t.place).toLowerCase().includes(query.toLowerCase()));content=intro(tripsPage?'Your collection of elsewhere.':'Where to next?',tripsPage?'The plans you’re making. The places you keep coming back to.':'Discover a journey worth making your own.')+`<div class="section-head"><div class="tabs">${tripsPage?`<button data-filter="all" class="${filter==='all'?'active':''}">My trips</button><button data-filter="saved" class="${filter==='saved'?'active':''}">Saved inspiration</button>`:'<span class="kicker">TRAVELLER COLLECTIONS</span>'}</div><span class="muted">${list.length} trips</span></div><input class="search" id="search" aria-label="Search trips" placeholder="Search a destination or trip…" value="${escapeHTML(query)}"><div class="grid">${list.length?list.map(card).join(''):'<div class="empty"><h3>A new adventure belongs here.</h3><p class="muted">Create a trip or save inspiration from your friends.</p><button class="primary" data-create>Create a trip</button></div>'}</div>`}$('#app').innerHTML=content}
function detail(id){const t=state.trips.find(t=>t.id===id);if(!t){$('#app').innerHTML=intro('Trip not found','<a href="#trips">Return to your trips →</a>');return}if(!['itinerary','photos',...(t.imported?['transport','hotels','expenses']:[])].includes(tripTab))tripTab='itinerary';if(t.imported)return importedDetail(t);return genericDetail(t)}
function profile(){const features=worldData.features.filter(f=>f.properties.ISO_A3!=='ATA');$('#app').innerHTML=intro('Your world, one memory at a time.','Jamie Lee · Singapore · Always taking the scenic route.')+`<div class="stats"><div><strong>${state.visited.length}</strong><small>Countries visited</small></div><div><strong>${state.trips.filter(t=>t.own).length}</strong><small>Personal trips</small></div><div><strong>${state.saved.length}</strong><small>Saved adventures</small></div></div><div class="map-box"><span class="kicker">MY TRAVEL PASSPORT</span><svg viewBox="0 0 1000 440" role="img" aria-label="World map with your visited countries filled in green">${features.map(f=>{const rings=f.geometry.type==='Polygon'?f.geometry.coordinates:f.geometry.type==='Point'?[[[f.geometry.coordinates[0]-.5,f.geometry.coordinates[1]-.5],[f.geometry.coordinates[0]+.5,f.geometry.coordinates[1]-.5],[f.geometry.coordinates[0]+.5,f.geometry.coordinates[1]+.5],[f.geometry.coordinates[0]-.5,f.geometry.coordinates[1]+.5]]]:f.geometry.coordinates.flat();return `<path class="${state.visited.includes(f.properties.ISO_A3)?'visited':''}" d="${rings.map(r=>r.map((p,i)=>`${i?'L':'M'}${((p[0]+180)/360*1000).toFixed(1)},${((85-p[1])/145*430).toFixed(1)}`).join('')+'Z').join('')}"><title>${escapeHTML(f.properties.NAME)}</title></path>`}).join('')}</svg><p class="muted">● Green = visited · Tick a country below to update your map. Initial visits are illustrative.</p></div><div class="section-head"><h2>Put your memories on the map</h2></div><input class="search" id="country-search" aria-label="Search countries" placeholder="Find a country…"><div class="countries">${features.sort((a,b)=>a.properties.NAME.localeCompare(b.properties.NAME)).map(f=>`<label data-country-name="${escapeHTML(f.properties.NAME.toLowerCase())}"><input type="checkbox" data-country="${f.properties.ISO_A3}" ${state.visited.includes(f.properties.ISO_A3)?'checked':''}>${escapeHTML(f.properties.NAME)}</label>`).join('')}</div><p class="muted">Map data: Natural Earth · <a href="docs/assets/ATTRIBUTION.md">Attribution</a></p>`}
function create(){const d=$('#modal');d.innerHTML=`<form id="create-form"><span class="kicker">A NEW CHAPTER</span><h2 style="margin-top:12px">Where are you headed?</h2><p class="muted">Start with a plan, or remember a trip already taken.</p><label>Trip name<input name="title" required maxlength="80" placeholder="A long weekend in Kyoto"></label><label>Destination<input name="place" required maxlength="80" placeholder="Kyoto, Japan"></label><label>Number of days<input name="days" type="number" min="1" max="365" value="5" required></label><label>Trip status<select name="status"><option>Planned</option><option>Ongoing</option><option>Completed</option><option>Draft</option></select></label><div class="dialog-actions"><button type="button" id="cancel">Cancel</button><button class="primary">Create trip</button></div></form>`;d.showModal();$('#cancel').onclick=()=>d.close()}
$('#new-trip').onclick=create;
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.go)location.hash=d.go;if('create'in d)create();if(d.open)location.hash='trip/'+d.open;if(d.filter){filter=d.filter;render()}for(const key of ['save','like'])if(d[key]){const arr=key==='save'?state.saved:state.liked;const i=arr.indexOf(d[key]);i<0?arr.push(d[key]):arr.splice(i,1);persist();render()}if(d.copy){const source=state.trips.find(t=>t.id===d.copy);const copy={...structuredClone(source),id:newTripId(),author:'Jamie Lee',own:true,status:'Draft',title:source.title+' — my trip',stops:source.stops.map(s=>({...s,done:false}))};state.trips.push(copy);persist();location.hash='trip/'+copy.id;notify('Itinerary copied to your private trips')}if(d.remove!==undefined){state.trips.find(t=>t.id===d.trip).stops.splice(Number(d.remove),1);persist();render()}});
document.addEventListener('submit',e=>{if(e.target.id==='create-form'){e.preventDefault();const data=new FormData(e.target);if(!data.get('title').trim()||!data.get('place').trim())return;const t={id:newTripId(),title:data.get('title').trim(),place:data.get('place').trim(),days:Number(data.get('days')),status:data.get('status'),author:'Jamie Lee',own:true,image:'mountain',stops:[]};state.trips.push(t);persist();$('#modal').close();location.hash='trip/'+t.id;notify('Your new trip is ready')}if(e.target.id==='add-stop'){e.preventDefault();const input=e.target.elements.stop;if(!input.value.trim())return;state.trips.find(t=>t.id===e.target.dataset.trip).stops.push({name:input.value.trim(),done:false,...(e.target.elements.day?{day:Number(e.target.elements.day.value),time:e.target.elements.time.value,notes:[]}: {})});persist();render();$('#add-stop input').focus()}});
document.addEventListener('change',e=>{const d=e.target.dataset;if(d.stop!==undefined){state.trips.find(t=>t.id===d.trip).stops[Number(d.stop)].done=e.target.checked;persist();render()}if(e.target.id==='status'){state.trips.find(t=>t.id===d.trip).status=e.target.value;persist();render()}if(d.country){const search=$('#country-search').value;state.visited=e.target.checked?[...new Set([...state.visited,d.country])]:state.visited.filter(c=>c!==d.country);persist();profile();$('#country-search').value=search;filterCountries(search);document.querySelector(`[data-country="${d.country}"]`).focus()}});
function filterCountries(value){document.querySelectorAll('[data-country-name]').forEach(l=>l.hidden=!l.dataset.countryName.includes(value.toLowerCase()))}
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}if(e.target.id==='country-search')filterCountries(e.target.value)});
window.addEventListener('hashchange',()=>{query='';filter='all';tripTab='itinerary';selectedTripDay='all';render();window.scrollTo(0,0)});enrichFriendExamples();render();

if(typeof navigator!=='undefined')setupOffline();
